//! Independent positive source inputs. Not generated by a builder/walker and not executed.
use mori_core::sherlock::helper_machine::shared::i128_class::KIntC;
use mori_core::sherlock::helper_machine::shared::owner_ext_source_program::ExtProgram;
use mori_core::sherlock::helper_machine::shared::owner_ext_t3_uses::{ExtArm, ExtExpr, ExtFunction, ExtParamSrc, ExtPattern, ExtValue};
use mori_core::sherlock::helper_machine::shared::owner_ext_type_builder::{CtorDeclSrc, CtorFieldSrc, TypeDeclSrc, TypeExprSrc};
use mori_core::sherlock::helper_machine::shared::{CorePattern, CoreValue};
fn named(n: &str) -> TypeExprSrc { TypeExprSrc::Named { name: n.into() } }
fn apply(n: &str, arg: TypeExprSrc) -> TypeExprSrc { TypeExprSrc::Apply { name: n.into(), args: vec![arg] } }
fn param(n: &str) -> TypeExprSrc { TypeExprSrc::Param { name: n.into() } }
fn field(n: &str, ty: TypeExprSrc) -> CtorFieldSrc { CtorFieldSrc { name: n.into(), ty } }
fn ctor(n: &str, fields: Vec<CtorFieldSrc>) -> CtorDeclSrc { CtorDeclSrc { name: n.into(), fields } }
fn uint(n: u128) -> ExtExpr { ExtExpr::Literal { value: ExtValue::Core { value: CoreValue::UInt { n: KIntC::InRange(n) } } } }
fn var(n: &str) -> ExtExpr { ExtExpr::Var { name: n.into() } }
fn pat(ty: TypeExprSrc, n: &str, fields: Vec<ExtPattern>) -> ExtPattern { ExtPattern::Ctor { ty, ctor: n.into(), fields } }
fn arm(pattern: ExtPattern, body: ExtExpr) -> ExtArm { ExtArm { pattern, body } }

/// T1 mutually recursive Dawn/Dusk; T3 Chain instances discover Tag through fields.
pub fn generic_fifo_after_signature() -> ExtProgram {
    ExtProgram {
        types: vec![
            TypeDeclSrc { name: "Dawn".into(), parameters: vec![], ctors: vec![
                ctor("Rise", vec![]), ctor("Pair", vec![field("peer", named("Dusk"))]),
            ] },
            TypeDeclSrc { name: "Dusk".into(), parameters: vec![], ctors: vec![
                ctor("Night", vec![]), ctor("Loop", vec![field("peer", named("Dawn"))]),
            ] },
            TypeDeclSrc { name: "Chain".into(), parameters: vec!["T".into()], ctors: vec![
                ctor("End", vec![]), ctor("Step", vec![
                    field("value", param("T")),
                    field("rest", apply("Chain", param("T"))),
                    field("seal", apply("Tag", param("T"))),
                ]),
            ] },
            TypeDeclSrc { name: "Tag".into(), parameters: vec!["U".into()], ctors: vec![
                ctor("Mark", vec![field("payload", param("U"))]),
            ] },
        ], assets: vec![], states: vec![], inputs: vec![],
        functions: vec![
            ExtFunction { name: "Acarry".into(), parameters: vec![ExtParamSrc { name: "Astream".into(), ty: apply("Chain", TypeExprSrc::UInt) }], return_type: apply("Chain", TypeExprSrc::UInt), body: var("Astream") },
            ExtFunction { name: "Inspect".into(), parameters: vec![ExtParamSrc { name: "phase".into(), ty: named("Dawn") }], return_type: TypeExprSrc::UInt,
                body: ExtExpr::Match { scrutinee: Box::new(var("phase")), arms: vec![
                    arm(pat(named("Dawn"), "Pair", vec![pat(named("Dusk"), "Loop", vec![pat(named("Dawn"), "Rise", vec![])])]), uint(3)),
                    arm(pat(named("Dawn"), "Rise", vec![]), uint(0)),
                    arm(pat(named("Dawn"), "Pair", vec![ExtPattern::Dedicated { pattern: CorePattern::PVar { x: "Abuddy".into() } }]), uint(1)),
                ] },
            },
            ExtFunction { name: "Zkeep".into(), parameters: vec![ExtParamSrc { name: "other".into(), ty: apply("Chain", TypeExprSrc::Bool) }], return_type: apply("Chain", TypeExprSrc::Bool), body: var("other") },
        ],
        entry: ExtExpr::Let { name: "token".into(),
            value: Box::new(ExtExpr::Literal { value: ExtValue::Constructor { ty: apply("Chain", TypeExprSrc::Bool), ctor: "End".into(), fields: vec![] } }),
            body: Box::new(ExtExpr::Construct { ty: apply("Chain", TypeExprSrc::UInt), ctor: "End".into(), fields: vec![] }),
        },
    }
}

/// No constructor or pattern use: the first signature alone must instantiate Ribbon<UInt>.
pub fn signature_only_reuse() -> ExtProgram {
    ExtProgram {
        types: vec![TypeDeclSrc { name: "Ribbon".into(), parameters: vec!["Q".into()], ctors: vec![
            ctor("Bare", vec![]),
            ctor("Knot", vec![field("head", param("Q")), field("tail", apply("Ribbon", param("Q")))]),
        ] }], assets: vec![], states: vec![], inputs: vec![],
        functions: vec![
            ExtFunction { name: "Arelay".into(), parameters: vec![ExtParamSrc { name: "Apacket".into(), ty: apply("Ribbon", TypeExprSrc::UInt) }], return_type: apply("Ribbon", TypeExprSrc::UInt), body: var("Apacket") },
            ExtFunction { name: "Zrepeat".into(), parameters: vec![ExtParamSrc { name: "again".into(), ty: apply("Ribbon", TypeExprSrc::UInt) }], return_type: TypeExprSrc::UInt, body: uint(7) },
        ], entry: uint(5),
    }
}
